set -e; cat > /app/sqlserver-v2/server.py <<'PY'
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import hashlib,ipaddress,socketserver,threading
R=Path('/app/sqlserver-v2'); status_enabled={'value':True}
def secret(name): return (R/name).read_text().strip()
def bearer(h): return h.headers.get('Authorization','').removeprefix('Bearer ')
class API(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def reply(self,code): self.send_response(code); self.send_header('Content-Length','0'); self.end_headers()
 def control(self): return bearer(self)==secret('diagnostic-control.token')
 def do_POST(self):
  if self.path=='/diagnostics' and self.control(): return self.reply(201)
  if self.path=='/admin/disable-status' and self.control(): status_enabled['value']=False; return self.reply(204)
  self.reply(403)
 def do_HEAD(self): self.reply(204 if self.path=='/diagnostics' and self.control() else 403)
 def do_GET(self): self.reply(200 if self.path=='/status' and status_enabled['value'] and bearer(self)==secret('status-reader.token') else 401)
class DB(socketserver.StreamRequestHandler):
 def handle(self):
  fields=self.rfile.readline().decode().strip().split(' ',2); peer=ipaddress.ip_address(self.client_address[0]); allowed=ipaddress.ip_network((R/'allowed-cidr').read_text().strip())
  if peer not in allowed: self.wfile.write(b'NETWORK_REJECTED\n'); return
  if len(fields)!=3 or fields[0]!=secret('inventory.password'): self.wfile.write(b'AUTHENTICATION_FAILURE\n'); return
  if fields[1]!='inventory': self.wfile.write(b'DATABASE_NOT_FOUND\n'); return
  self.wfile.write(b'CONNECTED login=inventory-diagnostic role=db_datareader\n'); self.wfile.flush()
  while True:
   q=self.rfile.readline()
   if not q: break
   self.wfile.write(b'ROW inventory_records=4\n'); self.wfile.flush()
class TCP(socketserver.ThreadingTCPServer): allow_reuse_address=True
api=ThreadingHTTPServer(('0.0.0.0',18190),API); db=TCP(('0.0.0.0',14330),DB); threading.Thread(target=db.serve_forever,daemon=True).start(); api.serve_forever()
PY
cat > /app/sqlserver-v2/diagnose.py <<'PY'
from pathlib import Path
import socket,sys,time,urllib.error,urllib.request
R=Path('/app/sqlserver-v2'); ident,token_path,password_path,database,mode=sys.argv[1:6]; token=Path(token_path).read_text().strip(); req=urllib.request.Request('http://'+(R/'bridge-ip').read_text().strip()+':18190/diagnostics',method='POST',headers={'Authorization':'Bearer '+token})
try:
 with urllib.request.urlopen(req,timeout=4) as r: code=r.status
except urllib.error.HTTPError as e: code=e.code
print(f'diagnostic={ident} control_http={code}',flush=True)
if ident=='diag-refused':
 try: socket.create_connection(((R/'bridge-ip').read_text().strip(),14331),1)
 except OSError: print('diagnostic=diag-refused outcome=CONNECTION_REFUSED',flush=True); raise SystemExit(0)
password=Path(password_path).read_text().strip(); s=socket.create_connection(((R/'bridge-ip').read_text().strip(),14330),4); s.sendall(f'{password} {database} {ident}\n'.encode()); reply=s.makefile('rb').readline().decode().strip(); print(f'diagnostic={ident} outcome={reply}',flush=True)
if reply.startswith('CONNECTED') and mode=='hold':
 while True:
  s.sendall(b'SELECT inventory\n'); print(f'diagnostic={ident} '+s.makefile('rb').readline().decode().strip(),flush=True); time.sleep(2)
s.close()
